; =============================================================================
; DHGR Pinwheel over Sunset Gradient
; =============================================================================
; A 6502 program for the Apple II that enters Double-Hi-Res (DHGR) mode and
; draws a ROUND 7-blade curved pinwheel centered on the screen, over a vertical
; 6-band sunset gradient (blue / purple / red / orange / yellow / pink) with a
; 4-row checkerboard dither between each pair of bands.
;
; Designed and verified against JACE (the 65C02 Apple II emulator in this repo).
;
; GEOMETRY / RESOLUTION
; ---------------------
 ; * The DHGR screen is 560x192 raw pixels. The scanner reads, per row, 40 bytes
 ;   from each bank (MAIN + AUX). For each even byte-offset it combines
 ;   aux[o], main[o], aux[o+1], main[o+1] into a 28-bit word (bits 0-6=aux[o],
 ;   7-13=main[o], 14-20=aux[o+1], 21-27=main[o+1]). That word is 7 nibbles and
 ;   each nibble drives 4 pixels through the FLIP_NYBBLE remap -> 28 pixels per
 ;   word, 20 words/row x 28 = 560.
 ; * Real DHGR is PER-PIXEL: 560 independent 4-bit colors per row, defined in
 ;   YIQ / the NTSC color clock (advanced-assembly.md section 3d). This example
 ;   stays on a 140-column x 192-row grid (4 raw px per column) by keeping each
 ;   nibble constant -- a layout/porting simplification, the constant-nibble
 ;   special case of the per-pixel model.
 ; * A solid color is NOT a run of identical bytes -- each of the 4 byte slots in
 ;   a word carries a different value (see the precomputed tables).
;
; * APPLE II DISPLAYS DHGR WITH 2:1 TALL PIXELS: raw 560x192 shows as 560x384.
;   A shape drawn with equal raw width and height therefore looks like a 2:1
;   ellipse. To make the pinwheel ROUND, the design is computed in DISPLAY
;   space: column c, row r maps to display pixel (4*c, 2*r). The pinwheel is a
;   display-space circle centered at (280,192):
;       (4*(c - 70))^2 + (2*(r - 96))^2 <= R^2
;   i.e. the raw shape is 2x as wide as it is tall, which displays as a circle.
;
; HOW IT WORKS (render path)
; --------------------------
; * The 192 DRAM rows are NOT linear in memory. Each row's byte address is
;   ((y>>3)&7)*128 + 40*(y>>6) + (y&7)*1024  +  $2000, matching the Apple II
;   DRAM refresh geometry (and JACE's calculateHiresOffset()). The row_hi /
;   row_lo tables encode this.
;
; * Each row is 40 bytes per bank (interleaved main/aux in the video, written as
;   one 40-byte contiguous block per bank). We render with a TWO-PASS approach:
;   with PAGE2 off we copy the row's 40 MAIN bytes to the row address; with
;   PAGE2 on we copy the row's 40 AUX bytes to the SAME address. This avoids
;   per-byte softswitch toggling.
;
; CRITICAL LAYOUT CONSTRAINTS (learned the hard way)
; -------------------------------------------------
; 1. All program DATA must sit in $8000-$9FFF or other non-video RAM. The code
;    lives at $800. The 7680-byte main table is at $6000 and the 7680-byte aux
;    table at $7E00 -- both in plain RAM that the video scanner never touches.
;    ($2000-$3FFF is DHGR page-1 video and $4000-$5FFF is page-2 video; putting
;    data there makes it disappear/corrupt mid-render.)
; 2. When copying a bank's row bytes with PAGE2 on/off, you MUST re-point the
;    destination ($30/$31) before the AUX pass: the copy routine advances the
;    destination pointer by 40 bytes, so reusing it would write the aux row one
;    DRAM row too far.
; 3. The copy routine is PAGE-SAFE: (zp),Y / (abs),Y do not carry when the low
;    byte crosses $FF, so a naive byte loop corrupts across page boundaries.
;    copy40 below splits the 40-byte copy at any page boundary and does the
;    high-byte bump by hand.
;
; ZERO-PAGE MAP
; -------------
;   $30/$31  destination address (row video address), set before each pass
;   $34/$35  source address (row data pointer in the main/aux table)
;   $36      bytes remaining in this 40-byte copy
;   $38      bytes in the current sub-segment (<= 40, page-bounded)
;   $3A      current row index (Y is clobbered by copy40, so we save it)
;
; BUILD & RUN (from the jace repo root)
; -------------------------------------
;   acme -f apple -o /tmp/dhgr-pinwheel.apple examples/dhgr-pinwheel/dhgr-pinwheel.asm
;   # strip the 4-byte Apple II header, then load and run in JACE:
;   ./jace --terminal   ; then:  loadbin /tmp/dhgr-pinwheel.bin 800 ; 800G ; run
; See dhgr-pinwheel-test.sh for the one-shot script.
; =============================================================================
* = $800

init:
    stx $C05F
    stx $C056
    stx $C00C
    stx $C052
    stx $C050
    stx $C000
    stx $C054
    stx $C05E
    stx $C057
    stx $C00D
    stx $C001

    ldy #0
rowloop:
    sty $3A
    lda row_hi,y
    sta $31
    lda row_lo,y
    sta $30
    lda #$00
    sta $C054
    lda mptr_lo,y
    sta $34
    lda mptr_hi,y
    sta $35
    jsr copy40
    ldy $3A
    lda row_hi,y
    sta $31
    lda row_lo,y
    sta $30
    lda #$FF
    sta $C055
    lda aptr_lo,y
    sta $34
    lda aptr_hi,y
    sta $35
    jsr copy40
    ldy $3A
    iny
    cpy #192
    bne rowloop

done:
    jmp done

; copy 40 bytes from ($34,$35) to ($30,$31), page-safe
copy40:
    lda #$28
    sta $36
cloop:
    lda $36
    sta $38
    lda $34
    eor #$FF
    clc
    adc #1
    bne src_cmp
    jmp src_done
src_cmp:
    cmp $38
    bcs src_done
    sta $38
src_done:
    lda $30
    eor #$FF
    clc
    adc #1
    bne dst_cmp
    jmp dst_done
dst_cmp:
    cmp $38
    bcs dst_done
    sta $38
dst_done:
    ldy #0
cseg:
    lda ($34),y
    sta ($30),y
    iny
    cpy $38
    bne cseg
    lda $38
    clc
    adc $34
    sta $34
    bcc s1
    inc $35
s1:
    lda $38
    clc
    adc $30
    sta $30
    bcc s2
    inc $31
s2:
    lda $36
    sec
    sbc $38
    sta $36
    bne cloop
    rts

